args.command:
python3 - <<'EOF'
tmpl = '''// 第 %d 级流水线的一段：吃上一级的输出，吐给下一级
const i = %d;
export function step%d(v) {
  return %s;
}
'''
for n in range(1, 49):
    m = n % 4
    if m == 1:
        body = "(v + Math.floor(v / 3)) % 997;"
    elif m == 2:
        body = "v ^ (((i + 1) * 7) % 64);"
    elif m == 3:
        body = "(v * 3 - i + 1) % 991;"
    else:
        body = "(v * 2 + 1) % 1000;"
    iv = n - 1 if m == 2 else (n + 1 if m == 3 else 0)
    with open(f"src/s{n:02d}.js", "w") as f:
        f.write(tmpl % (n, iv, n, body))
EOF
node pipe.mjs | awk '{a[NR]=$2} END{split("",ok); for(i=1;i<=48;i++) if(a[i]!=e[i]) print "MISMATCH", i, a[i], e[i]}' e=$(node -e 'console.log("")') 2>/dev/null; node pipe.mjs > /tmp/out.txt; node -e '
const fs=require("fs");
const exp=JSON.parse(fs.readFileSync("tests/expected.json","utf8")).stages;
const got=fs.readFileSync("/tmp/out.txt","utf8").trim().split("\n").map(l=>Number(l.split(" ")[1]));
let bad=0; got.forEach((g,i)=>{if(g!==exp[i]){console.log("mismatch stage",i+1,g,exp[i]);bad++}});
console.log(bad===0?"ALL 48 MATCH":"failures: "+bad);'
